import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 4 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"4","title":"Page 4 | Home","prev":"/page/3/","next":"/page/5/","posts":[{"title":"无限滚动加载列表","url":"/posts/2023-06-03-scroll-loader/","date":"2023-06-03 12:55","tags":["web"],"html":"<p>滚动加载是分页显示列表常用的一个技术，具体的实现方式基本上后端都会在返回数据上给一个 <code>cursor</code> 字段，前端在请求下一页的时候会把这个字段带上，后端根据这个字段来返回下一页的数据。这种方式的好处是可以在前端缓存数据，减少请求次数，但是缺点也很明显，就是无法跳页，只能一页一页的往下翻。为此，我们要实现一个滚动加载组件，当这个组件在可视范围内的时候，会去加载下一页的数据。</p>\\n<h2 id=\\"核心技术点\\" tabindex=\\"-1\\">核心技术点 <a class=\\"header-anchor\\" href=\\"#核心技术点\\" aria-label=\\"Permalink to &quot;核心技术点&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>如果检测组件进入可视范围，我们可以使用 IntersectionObserver API，来监听元素进入可视范围。我们使用 React 实现一个组件，当这个组件进入可视范围的时候，会触发一个回调函数，这个回调函数会去加载下一页的数据。</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> ScrollLoader</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">FC</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">IScrollLoaderProps</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> ({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  inView,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  updateCompleted</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> loaderRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> observerRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">IntersectionObserver</span><span style=\\"color:#D73A49\\"> |</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">>(</span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> cursorRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">''</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#24292E\\"> [</span><span style=\\"color:#005CC5\\">completed</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">setCompleted</span><span style=\\"color:#24292E\\">] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> useState</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">false</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> fetchMore</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    inView</span><span style=\\"color:#24292E\\">?.(cursorRef.current).</span><span style=\\"color:#6F42C1\\">then</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">res</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      if</span><span style=\\"color:#24292E\\"> (res.nextCursor) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        cursorRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> res.nextCursor;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        if</span><span style=\\"color:#24292E\\"> (observerRef.current </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#24292E\\"> loaderRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">          // trigger the observer again</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          observerRef.current.</span><span style=\\"color:#6F42C1\\">unobserve</span><span style=\\"color:#24292E\\">(loaderRef.current);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          observerRef.current.</span><span style=\\"color:#6F42C1\\">observe</span><span style=\\"color:#24292E\\">(loaderRef.current);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        setCompleted</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">        updateCompleted</span><span style=\\"color:#24292E\\">?.(</span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, [inView, updateCompleted]);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> callbackFunction</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> IntersectionObserverCallback</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">    entries</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      entries.</span><span style=\\"color:#6F42C1\\">forEach</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">entry</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        if</span><span style=\\"color:#24292E\\"> (entry.isIntersecting </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#D73A49\\"> !</span><span style=\\"color:#24292E\\">completed) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          fetchMore</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    [completed, fetchMore]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  useEffect</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    const</span><span style=\\"color:#005CC5\\"> observerOptions</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      root: </span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      rootMargin: </span><span style=\\"color:#032F62\\">'0px'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      threshold: </span><span style=\\"color:#005CC5\\">0.5</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    observerRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> IntersectionObserver</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      callbackFunction,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      observerOptions</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (loaderRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      observerRef.current.</span><span style=\\"color:#6F42C1\\">observe</span><span style=\\"color:#24292E\\">(loaderRef.current);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      if</span><span style=\\"color:#24292E\\"> (observerRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        observerRef.current.</span><span style=\\"color:#6F42C1\\">disconnect</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        observerRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, [callbackFunction]);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (completed) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  } </span><span style=\\"color:#D73A49\\">else</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{styles.loader} </span><span style=\\"color:#6F42C1\\">ref</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{loaderRef}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;</span><span style=\\"color:#005CC5\\">Loading</span><span style=\\"color:#24292E\\"> /></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br><span class=\\"line-number\\">57</span><br><span class=\\"line-number\\">58</span><br><span class=\\"line-number\\">59</span><br><span class=\\"line-number\\">60</span><br><span class=\\"line-number\\">61</span><br><span class=\\"line-number\\">62</span><br><span class=\\"line-number\\">63</span><br><span class=\\"line-number\\">64</span><br><span class=\\"line-number\\">65</span><br><span class=\\"line-number\\">66</span><br><span class=\\"line-number\\">67</span><br><span class=\\"line-number\\">68</span><br></div></div><p>通过 inView 属性来传入回调函数，当组件进入可视范围的时候，会调用这个函数，然后去加载下一页的数据。这里我们使用了一个 cursor 来标记当前的页码，当请求下一页的时候，会把这个 cursor 传给后端，后端会根据这个 cursor 来返回下一页的数据。当后端返回的数据中没有 cursor 的时候，说明已经到了最后一页，这时候我们不再渲染这个组件。</p>\\n<h2 id=\\"边界情况处理\\" tabindex=\\"-1\\">边界情况处理 <a class=\\"header-anchor\\" href=\\"#边界情况处理\\" aria-label=\\"Permalink to &quot;边界情况处理&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当用户的屏幕非常长的时候，我们需要加载很多页的数据才能填满屏幕。但是 IntersectionObserver 在组件进入可视范围的时候只会触发一次回调，所以我们需要手动去重新触发。当组件加载完数据的时候，我们会先 unobserve，然后再重新 observe 这个组件，这样就可以触发回调函数了。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>滚动加载是一个很常见的需求，但是针对边界情况的处理很多人却忽略掉了。针对比较长的屏幕，需要我们做特殊处理才能满足需求。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/Intersection_Observer_API\\" target=\\"_blank\\" rel=\\"noreferrer\\">Intersection Observer API</a></p>\\n"},{"title":"拖拽排序列表","url":"/posts/2023-04-16-draggable-list/","date":"2023-04-16 12:31","tags":["web"],"html":"<p>拖拽排序是一个很常见的功能，在浏览器不支持原生拖拽功能的时代，人们只能使用鼠标的点击事件来模拟拖拽效果，手动控制拖拽元素的位置来进行移动操作。随着原生拖拽 API 的支持，在实现这个功能的时候就可以更简单一点了。</p>\\n<h2 id=\\"相关事件\\" tabindex=\\"-1\\">相关事件 <a class=\\"header-anchor\\" href=\\"#相关事件\\" aria-label=\\"Permalink to &quot;相关事件&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先，你要想拖拽某个元素的话必须设置属性 <code>draggable=&quot;true&quot;</code> 才可以进行拖拽操作。然后进行拖拽操作主要有以下事件需要处理。</p>\\n<ol>\\n<li>onDragStart 当拖拽开始的时候触发</li>\\n<li>onDragOver 当拖拽到某个元素内部的时候触发</li>\\n<li>onDragEnter 当拖拽进入某个元素的时候触发</li>\\n<li>onDragEnd 当鼠标松开，拖拽结束的时候触发</li>\\n<li>onDrop 当拖拽到某个元素并松开鼠标的时候触发</li>\\n</ol>\\n<p>由于我们使用拖拽进行排序，而不是拖拽元素放到别的元素里面，所以我们并不需要进行 drop 处理，当 dragOver 某个元素的时候也不需要额外的处理。所以这两个事件的代码最简单，我们只需要移除默认的事件响应。</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> dragOverHandler</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">((</span><span style=\\"color:#E36209\\">event</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">DragEvent</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLElement</span><span style=\\"color:#24292E\\">>) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  event.</span><span style=\\"color:#6F42C1\\">preventDefault</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  event.dataTransfer.dropEffect </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'move'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}, []);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> dropHandler</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">((</span><span style=\\"color:#E36209\\">event</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">DragEvent</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLElement</span><span style=\\"color:#24292E\\">>) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  event.</span><span style=\\"color:#6F42C1\\">stopPropagation</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  event.</span><span style=\\"color:#6F42C1\\">preventDefault</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}, []);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br></div></div><p>dropEffect 有四种，默认的是 <code>copy</code> 我们需要改成 <code>move</code> 才符合需求。接下来再来看看其他三个事件：</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> dragStartHandler</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  (</span><span style=\\"color:#E36209\\">event</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">DragEvent</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLElement</span><span style=\\"color:#24292E\\">>, </span><span style=\\"color:#E36209\\">index</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    event.dataTransfer.effectAllowed </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'move'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">    // set dataTransfer enable mobile drag</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    event.dataTransfer.</span><span style=\\"color:#6F42C1\\">setData</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'text/plain'</span><span style=\\"color:#24292E\\">, index.</span><span style=\\"color:#6F42C1\\">toString</span><span style=\\"color:#24292E\\">());</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    dragItem.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> index;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    copyData.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> deepClone</span><span style=\\"color:#24292E\\">(sortedData);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    recordRect</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">    onDragStart</span><span style=\\"color:#24292E\\">?.();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  [sortedData, recordRect, onDragStart]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> dragEnterHandler</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  (</span><span style=\\"color:#E36209\\">index</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> number</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (dragItem.current </span><span style=\\"color:#D73A49\\">!==</span><span style=\\"color:#24292E\\"> index </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#24292E\\"> dragOverItem.current </span><span style=\\"color:#D73A49\\">!==</span><span style=\\"color:#24292E\\"> index) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      dragOverItem.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> index;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      const</span><span style=\\"color:#005CC5\\"> newData</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> deepClone</span><span style=\\"color:#24292E\\">(copyData.current);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      const</span><span style=\\"color:#005CC5\\"> dragData</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> newData[dragItem.current];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      newData.</span><span style=\\"color:#6F42C1\\">splice</span><span style=\\"color:#24292E\\">(dragItem.current, </span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      newData.</span><span style=\\"color:#6F42C1\\">splice</span><span style=\\"color:#24292E\\">(dragOverItem.current, </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">, dragData);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      setSortedData</span><span style=\\"color:#24292E\\">(newData);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      onDragEnter</span><span style=\\"color:#24292E\\">?.();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  [onDragEnter]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> dragEndHandler</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useCallback</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  updateData</span><span style=\\"color:#24292E\\">?.(sortedData);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  onDragEnd</span><span style=\\"color:#24292E\\">?.();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}, [sortedData, updateData, onDragEnd]);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br></div></div><ol>\\n<li>dragStart 的时候记录下当前的 index，并复制一份数组数据。</li>\\n<li>dragEnter 的时候记录下拖拽进入的元素 index，然后重新排序数组会渲染一个新的列表</li>\\n<li>dragEnd 的时候同步数据到上层，展示排序后的结果</li>\\n</ol>\\n<p>完整的代码请看文章最后的链接。</p>\\n<h2 id=\\"flip-动画\\" tabindex=\\"-1\\">FLIP 动画 <a class=\\"header-anchor\\" href=\\"#flip-动画\\" aria-label=\\"Permalink to &quot;FLIP 动画&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当进行拖拽排序的时候，我们想要加上元素移动的动画，可以更明显的感受到顺序的变化。 我们使用 FLIP 技术来完成这个效果。</p>\\n<ol>\\n<li>First: 记录当前元素的位置</li>\\n<li>Last: 记录更新后元素的位置</li>\\n<li>Invert: 计算元素在 X 方向和 Y 方向的偏移，然后使用 transform 进行移动</li>\\n<li>Play: 播放 transform 动画</li>\\n</ol>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">useEffect</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (draggable </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#24292E\\"> containerRef?.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    Array.</span><span style=\\"color:#6F42C1\\">from</span><span style=\\"color:#24292E\\">(containerRef.current.</span><span style=\\"color:#6F42C1\\">querySelectorAll</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'[data-id]'</span><span style=\\"color:#24292E\\">)).</span><span style=\\"color:#6F42C1\\">forEach</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      async</span><span style=\\"color:#E36209\\"> node</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> dom</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> node </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#6F42C1\\"> HTMLElement</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> key</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> dom.dataset.id </span><span style=\\"color:#D73A49\\">as</span><span style=\\"color:#005CC5\\"> string</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        const</span><span style=\\"color:#005CC5\\"> prevRect</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> prevRects.current[key];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        if</span><span style=\\"color:#24292E\\"> (key) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">          const</span><span style=\\"color:#005CC5\\"> rect</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> dom.</span><span style=\\"color:#6F42C1\\">getBoundingClientRect</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">          if</span><span style=\\"color:#24292E\\"> (prevRect) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            const</span><span style=\\"color:#005CC5\\"> dy</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> prevRect.y </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> rect.y;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            const</span><span style=\\"color:#005CC5\\"> dx</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> prevRect.x </span><span style=\\"color:#D73A49\\">-</span><span style=\\"color:#24292E\\"> rect.x;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            dom.style.pointerEvents </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'none'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            dom.</span><span style=\\"color:#6F42C1\\">animate</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              [</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                  transform: </span><span style=\\"color:#032F62\\">\`translate(\${</span><span style=\\"color:#24292E\\">dx</span><span style=\\"color:#032F62\\">}px, \${</span><span style=\\"color:#24292E\\">dy</span><span style=\\"color:#032F62\\">}px)\`</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                { transform: </span><span style=\\"color:#032F62\\">'translate(0, 0)'</span><span style=\\"color:#24292E\\"> }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              ],</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                duration: </span><span style=\\"color:#005CC5\\">TIMEOUT</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                easing: </span><span style=\\"color:#032F62\\">'linear'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            await</span><span style=\\"color:#005CC5\\"> Promise</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">allSettled</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              node.</span><span style=\\"color:#6F42C1\\">getAnimations</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">map</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">animation</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> animation.finished)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            dom.style.pointerEvents </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> ''</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          prevRects.current[key] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> rect;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}, [draggable, sortedData, containerRef]);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br></div></div><p>上面是示例代码，注意这里的 FLIP 动画加了一些特殊处理，我们使用 <code>pointerEvents</code> 禁用动画过程中的事件响应，因为动画过程中触发任何 drag 事件会导致 index 顺序被改动，然后无限进行排序操作。\\n这不是我们期望的结果，然后在动画结束的时候再取消这个 CSS 属性。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>使用原生的拖拽 API 来实现排序功能更简单和易用，但目前手机浏览器还不支持这个功能。排序中的过渡动画是一个难点，特别是动画过程中移除事件的响应。如果可以使用 JS 的方式来临时禁用所有事件的响应，应该可以处理的更优雅。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/API/HTML_Drag_and_Drop_API\\" target=\\"_blank\\" rel=\\"noreferrer\\">HTML Drag and Drop API</a></p>\\n<p><a href=\\"https://github.com/acgotaku/simple-drag-drop-sort-list\\" target=\\"_blank\\" rel=\\"noreferrer\\">simple-drag-drop-sort-list</a></p>\\n<p><a href=\\"https://aerotwist.com/blog/flip-your-animations/\\" target=\\"_blank\\" rel=\\"noreferrer\\">FLIP Your Animations</a></p>\\n<p><a href=\\"https://web.dev/drag-and-drop/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Using the HTML5 Drag and Drop API</a></p>\\n"},{"title":"QR code 生成的相关参数","url":"/posts/2023-03-03-qrcode-version/","date":"2023-03-03 20:42","tags":["qrcode"],"html":"<p>QR code 本身就是把文字生成一个二维码的过程，顶多指定一下纠错等级。但是有些硬件设备只支持特定参数的二维码，所以我就查了一下二维码的相关规范了解一下生成过程中需要哪些参数。</p>\\n<h2 id=\\"version\\" tabindex=\\"-1\\">version <a class=\\"header-anchor\\" href=\\"#version\\" aria-label=\\"Permalink to &quot;version&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>二维码有一个 version 参数，范围是从 1 到 40。 每个版本都具备固有的码元结构(码元数)，码元是指构成 QR 码的方形黑白点。“码元结构”是指二维码中的码元数。从版本 1(21 码元 ×21 码元)开始，在纵向和横向各自以 4 码元为单位递增，一直到版本 40(177 码元 ×177 码元)。规律是 4n +17 (n 代表版本号)。版本越大能容纳的信息就越多，一般是选择能容纳所需信息的最小版本即可。</p>\\n<h2 id=\\"error-correction-level\\" tabindex=\\"-1\\">error correction level <a class=\\"header-anchor\\" href=\\"#error-correction-level\\" aria-label=\\"Permalink to &quot;error correction level&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>QR 码具有纠错功能，保证二维码在丢失一定数据的情况下还是可以读取。纠错有四个级别分别是：</p>\\n<ol>\\n<li>L (Low) 纠错 7%</li>\\n<li>M (Medium) 纠错 15%</li>\\n<li>Q (Quartile) 纠错 25%</li>\\n<li>H (High) 纠错 30%</li>\\n</ol>\\n<p>纠错能力越高需要存储的信息就越多，对应需要的 version 就要越高。</p>\\n<h2 id=\\"mask\\" tabindex=\\"-1\\">mask <a class=\\"header-anchor\\" href=\\"#mask\\" aria-label=\\"Permalink to &quot;mask&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>mask 是为了防止二维码有大量空白或者填充，让扫描器尽可能容易的进行扫描。mask 方案目前有 8 种。</p>\\n<p><img src=\\"https://upload.wikimedia.org/wikipedia/commons/c/c8/QR_Code_Mask_Patterns.svg\\" alt=\\"Mask Pattern\\" loading=\\"lazy\\"></p>\\n<p>选择 mask 的方案有相关的标准可以自行查询，本质目标是让生成的图片尽量黑白相间，避免同一颜色的色块大量出现，方便扫描器读取数据。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>普通业务使用的二维码相关库应该只提供文本接口和纠错标准的设定，会根据文本长度和纠错标准来自动其他两个参数。但是针对特殊需求的情况下就需要把 version 和 mask 参数暴露出来。\\n同时因为手动指定 version 也会因为 version 版本太低导致无法生成合法的二维码的情况。使用的时候需要注意。我本身有修改一个版本可以传入底层参数，可以看一下参考链接。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://www.qrcode.com/en/about/version.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Information capacity and versions of QR Code</a></p>\\n<p><a href=\\"https://www.keyence.com/ss/products/auto_id/codereader/basic_2d/qr.jsp\\" target=\\"_blank\\" rel=\\"noreferrer\\">What is a QR code?</a></p>\\n<p><a href=\\"https://github.com/nayuki/QR-Code-generator\\" target=\\"_blank\\" rel=\\"noreferrer\\">QR Code generator</a></p>\\n<p><a href=\\"https://en.wikiversity.org/wiki/Reed%E2%80%93Solomon_codes_for_coders\\" target=\\"_blank\\" rel=\\"noreferrer\\">Reed–Solomon codes for coders</a></p>\\n<p><a href=\\"https://github.com/acgotaku/simple-qr-reader/blob/master/src/vendors/qrcode/qrcodegen.ts\\" target=\\"_blank\\" rel=\\"noreferrer\\">qrcodegen</a></p>\\n"}]},"relativePath":"page/4/index.md","filePath":"page/[page].md"}`),l={name:"page/4/index.md"};function p(e,o,r,c,t,i){return n(),a("div")}const u=s(l,[["render",p]]);export{b as __pageData,u as default};
